### Pola Reusable Composables
Composables adalah fungsi konvensi Vue (diawali `use...`) yang memanfaatkan Composition API untuk mengekapsulasi stateful logic:

```typescript
// composables/useFetchCourses.ts
import { ref, onMounted } from 'vue';

export function useFetchCourses() {
  const courses = ref<any[]>([]);
  const isLoading = ref(true);
  const error = ref<string | null>(null);

  async function loadCourses() {
    isLoading.value = true;
    error.value = null;
    try {
      const res = await fetch('/api/courses');
      if (!res.ok) throw new Error('Gagal memuat data');
      courses.value = await res.json();
    } catch (err: any) {
      error.value = err.message || 'Terjadi kesalahan jaringan';
    } finally {
      isLoading.value = false;
    }
  }

  onMounted(loadCourses);

  return { courses, isLoading, error, refetch: loadCourses };
}
```

### State Management dengan Pinia
Pinia adalah store resmi Vue 3 yang ringan dan fully type-safe:

```typescript
// stores/cart.ts
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';

export const useCartStore = defineStore('cart', () => {
  const items = ref<string[]>([]);

  const itemCount = computed(() => items.value.length);

  function addItem(courseId: string) {
    if (!items.value.includes(courseId)) {
      items.value.push(courseId);
    }
  }

  function removeItem(courseId: string) {
    items.value = items.value.filter((id) => id !== courseId);
  }

  return { items, itemCount, addItem, removeItem };
});
```

### Skenario
Halaman eksplorasi kursus memiliki filter kategori dan pencarian keyword. Input teks yang memicu reaktivitas langsung sering membuat UI berkedip karena request berulang.

### Tugas
Buat composable `useDebouncedRef` yang menunda perubahan state reaktif sampai pengguna berhenti mengetik selama periode waktu tertentu.

```typescript
// composables/useDebouncedRef.ts
import { customRef } from 'vue';

export function useDebouncedRef<T>(value: T, delay = 300) {
  let timeout: ReturnType<typeof setTimeout>;
  return customRef((track, trigger) => {
    return {
      get() {
        track(); // Daftarkan dependensi reaktif
        return value;
      },
      set(newValue: T) {
        clearTimeout(timeout);
        timeout = setTimeout(() => {
          value = newValue;
          trigger(); // Picu update reaktif setelah jeda delay
        }, delay);
      }
    };
  });
}
```

```tsx
import React, { useState, useEffect, useMemo, useCallback } from 'react';

interface Lesson {
  id: number;
  title: string;
  durationMinutes: number;
  completed: boolean;
}

export function CourseProgressTracker({ initialLessons }: { initialLessons: Lesson[] }) {
  const [lessons, setLessons] = useState<Lesson[]>(initialLessons);
  const [filterQuery, setFilterQuery] = useState('');

  // Toggle status pelajaran tanpa memutasi array asli
  const toggleLesson = useCallback((id: number) => {
    setLessons((prev) =>
      prev.map((item) =>
        item.id === id ? { ...item, completed: !item.completed } : item
      )
    );
  }, []);

  // Perhitungan ter-memoize untuk mencegah re-kalkulasi yang tidak perlu
  const stats = useMemo(() => {
    const total = lessons.length;
    const completedCount = lessons.filter((l) => l.completed).length;
    const percentage = total === 0 ? 0 : Math.round((completedCount / total) * 100);
    return { total, completedCount, percentage };
  }, [lessons]);

  // Filter lessons
  const filteredLessons = useMemo(() => {
    return lessons.filter((l) =>
      l.title.toLowerCase().includes(filterQuery.toLowerCase())
    );
  }, [lessons, filterQuery]);

  return (
    <div className="p-6 bg-white rounded-xl shadow border">
      <div className="mb-4">
        <h2 className="text-xl font-bold">Progres Belajar: {stats.percentage}%</h2>
        <div className="w-full bg-gray-200 h-3 rounded-full mt-2">
          <div
            className="bg-blue-600 h-3 rounded-full transition-all"
            style={{ width: `${stats.percentage}%` }}
          />
        </div>
        <p className="text-sm text-gray-500 mt-1">
          {stats.completedCount} dari {stats.total} modul selesai.
        </p>
      </div>

      <input
        type="text"
        placeholder="Cari materi..."
        value={filterQuery}
        onChange={(e) => setFilterQuery(e.target.value)}
        className="w-full p-2 border rounded mb-4"
      />

      <ul className="space-y-2">
        {filteredLessons.map((lesson) => (
          <li
            key={lesson.id}
            onClick={() => toggleLesson(lesson.id)}
            className={`p-3 rounded border cursor-pointer flex justify-between ${
              lesson.completed ? 'bg-green-50 border-green-300' : 'bg-gray-50'
            }`}
          >
            <span>{lesson.title} ({lesson.durationMinutes} mnt)</span>
            <span>{lesson.completed ? '✅' : '⭕'}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

### Pola Custom Hook untuk Abstraksi Logika
Pisahkan logika bisnis dari UI presentasional:

```tsx
// hooks/useLocalStorage.ts
import { useState, useEffect } from 'react';

export function useLocalStorage<T>(key: string, initialValue: T) {
  const [storedValue, setStoredValue] = useState<T>(() => {
    if (typeof window === 'undefined') return initialValue;
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.warn(`Error reading localStorage key "${key}":`, error);
      return initialValue;
    }
  });

  useEffect(() => {
    try {
      window.localStorage.setItem(key, JSON.stringify(storedValue));
    } catch (error) {
      console.warn(`Error setting localStorage key "${key}":`, error);
    }
  }, [key, storedValue]);

  return [storedValue, setStoredValue] as const;
}
```

### Context API vs External Store (Zustand)
Gunakan Context API hanya untuk data yang jarang berubah (tema gelap/terang, locale bahasa). Untuk state sering berubah dengan performa tinggi, gunakan store eksternal seperti Zustand yang mendukung *selective subscription*:

```typescript
// store/useAuthStore.ts
import { create } from 'zustand';

interface AuthState {
  user: { id: string; name: string } | null;
  setUser: (user: { id: string; name: string } | null) => void;
}

export const useAuthStore = create<AuthState>((set) => ({
  user: null,
  setUser: (user) => set({ user }),
}));
```

### Skenario
Daftar 1.000 pertanyaan kuis sering mengalami lag input saat pengguna memilih radio button jawaban. Setiap pilihan memicu render ulang seluruh daftar 1.000 komponen kuis anak.

### Tugas
Terapkan `React.memo` dengan perbandingan props yang tepat, serta pastikan callback fungsi dipertahankan referensinya menggunakan `useCallback` agar hanya item yang berubah saja yang dirender ulang.

```tsx
import React, { memo } from 'react';

interface QuestionItemProps {
  id: number;
  text: string;
  isSelected: boolean;
  onSelect: (id: number) => void;
}

// Dibungkus React.memo agar tidak re-render jika isSelected dan onSelect tetap sama
export const QuestionItem = memo(function QuestionItem({
  id,
  text,
  isSelected,
  onSelect
}: QuestionItemProps) {
  console.log(`Render Question ${id}`);
  return (
    <div
      onClick={() => onSelect(id)}
      className={`p-3 border rounded ${isSelected ? 'bg-indigo-50 border-indigo-500' : ''}`}
    >
      <input type="radio" checked={isSelected} readOnly className="mr-2" />
      {text}
    </div>
  );
});
```

```php
<?php

declare(strict_types=1);

namespace LearnHub\Domain;

enum EnrollmentStatus: string
{
    case PENDING = 'pending';
    case ACTIVE = 'active';
    case COMPLETED = 'completed';
    case CANCELLED = 'cancelled';
}

final readonly class Student
{
    public function __construct(
        public string $id,
        public string $name,
        public string $email,
        public \DateTimeImmutable $registeredAt
    ) {}
}

final class CourseEnrollment
{
    public function __construct(
        public readonly Student $student,
        public readonly string $courseId,
        public EnrollmentStatus $status = EnrollmentStatus::PENDING,
        private ?\DateTimeImmutable $completedAt = null
    ) {}

    public function activate(): void
    {
        if ($this->status !== EnrollmentStatus::PENDING) {
            throw new \DomainException('Hanya pendaftaran berstatus pending yang dapat diaktifkan.');
        }
        $this->status = EnrollmentStatus::ACTIVE;
    }

    public function getLabel(): string
    {
        return match ($this->status) {
            EnrollmentStatus::PENDING => 'Menunggu Pembayaran',
            EnrollmentStatus::ACTIVE => 'Sedang Belajar',
            EnrollmentStatus::COMPLETED => 'Selesai Belajar',
            EnrollmentStatus::CANCELLED => 'Dibatalkan',
        };
    }
}
