                  title: Text(course.title, style: const TextStyle(fontWeight: FontWeight.bold)),
                  subtitle: Text('Rp ${course.price.toString()}'),
                  trailing: const Icon(Icons.arrow_forward_ios, size: 16),
                  onTap: () {
                    // Navigasi ke detail
                  },
                ),
              );
            },
          );
        },
      ),
    );
  }
}
